    scopeKicker: "Ambito del progetto",
    scopeTitle: "CREA3 — Risoluzione dei conflitti con algoritmi equitativi",
    scopeTagline: "Risoluzione online delle controversie assistita da IA e teoria dei giochi per l'Europa.",
    scopeChip1: "Si basa su CREA & CREA2",
    scopeChip2: "Programma EU JUST",
    scopeChip3: "Open source",
    scopeIntro1: "CREA3 porta strumenti guidati dall'IA e algoritmi di teoria dei giochi nella risoluzione delle controversie civili. Guida le persone passo dopo passo verso un risultato equo, efficiente e su misura, aiutandole a trovare le informazioni necessarie lungo il percorso.",
    scopeIntro2: "Parallelamente, affronta le differenze tra i sistemi giuridici nazionali degli Stati membri dell'UE affinché le controversie transfrontaliere possano essere gestite su una base comune.",
    scopeEcgarTitle: "Diritti disponibili comuni europei (ECGAR)",
    scopeEcgarText: "Le norme obbligatorie di ciascuno Stato membro vengono messe da parte e la procedura opera sui restanti “diritti disponibili”. L'obiettivo è ampliare l'accesso alla Risoluzione Online delle Controversie (ODR) e ridurre le barriere strutturali alla giustizia.",
    scopeWpHeading: "Tre innovazioni",
    scopeWp1Title: "Standard legali & IA",
    scopeWp1Body: "Collega l'ECGAR al modello di teoria dei giochi per stabilire standard precisi per l'integrazione del diritto e dell'IA.",
    scopeWp2Title: "Interfaccia conversazionale intelligente",
    scopeWp2Body: "Strumenti di machine learning alimentano un assistente che guida praticanti, professionisti legali e utenti comuni attraverso l'intera procedura.",
    scopeWp3Title: "Certificazione blockchain",
    scopeWp3Body: "La tecnologia dei contratti intelligenti, costruita con una metodologia di design DApp, certifica l'accordo raggiunto tra le parti.",
    scopeVideoNote: "Una funzione di videoconferenza integrata consente al mediatore di incontrare entrambe le parti all'interno della piattaforma (WP3).",
    scopeAudienceHeading: "A chi è rivolto",
    scopeAudienceNote: "CREA3 migliora la piattaforma CREA esistente ed è rilasciato come open source, per un'ampia gamma di stakeholder dell'UE.",
