    othersReferences: "Riferimenti europei",
    othersRefsIntro: "Fonti esterne e autorevoli sui diritti della giustizia e dei consumatori dell'UE. Si aprono in una nuova scheda.",
    othersInt1Title: "Ambito del progetto",
    othersInt1Body: "Cosa è CREA3, i suoi obiettivi e come si basa sulla precedente piattaforma CREA.",
