    othersInt5Body: "Gestisci la tua email, password, preferenze di notifica e dati.",
    othersExt1Title: "Portale europeo della giustizia elettronica",
    othersExt1Body: "Il punto unico dell'UE per informazioni e procedure giuridiche negli Stati membri.",
    othersExt2Title: "EUR-Lex",
    othersExt2Body: "Accesso ufficiale al diritto dell'Unione Europea, trattati e giurisprudenza.",
    othersExt3Title: "La tua Europa",
    othersExt3Body: "Guida pratica sui diritti dei cittadini e delle imprese nell'UE.",
    othersWebsiteTitle: "Sito del progetto",
    othersWebsiteBody: "La pagina ufficiale del progetto CREA3.",
    faqTitle: "Domande frequenti",
    faqIntro: "Risposte a domande comuni su account, gestione di una controversia e la piattaforma.",
    faqSearchPlaceholder: "Cerca nelle FAQ…",
    faqEmpty: "Nessuna domanda corrisponde alla tua ricerca.",
    faqCat1Title: "Iniziare",
    faqCat1Q1: "Come creo un account?",
    faqCat1A1: "Apri “Registrati”, inserisci la tua email e una password, e invia. La registrazione e l'identità sono gestite dal nostro servizio di accesso sicuro (Keycloak).",
    faqCat1Q2: "Come verifico la mia email?",
    faqCat1A2: "Dopo la registrazione ricevi un'email di verifica. Apri il link contenuto per attivare il tuo account. La verifica è obbligatoria prima di poter accedere.",
    faqCat1Q3: "Non ho ricevuto l'email di verifica — cosa faccio?",
    faqCat1A3: "Controlla prima la cartella spam. Se non è ancora arrivata dopo qualche minuto, prova ad accedere: la piattaforma offrirà di rinviare il messaggio di verifica.",
    faqCat1Q4: "Perché vedo “401 Non autorizzato”?",
    faqCat1A4: "La tua sessione è scaduta o non sei connesso. Accedi di nuovo; se persiste, disconnettiti completamente e riconnettiti per aggiornare la tua sessione.",
    faqCat2Title: "Gestire una controversia",
    faqCat2Q1: "Come avvio una controversia?",
    faqCat2A1: "Da “Le mie controversie”, crea una nuova controversia, dai un titolo, poi definisci gli elementi in gioco e registra le tue valutazioni di base.",
    faqCat2Q2: "Chi può invitare le altre parti?",
    faqCat2A2: "Solo il creatore della controversia può invitare le parti. Qualsiasi parte può invitare un mediatore. Gli inviti vengono inviati via email e possono essere accettati dall'area notifiche.",
    faqCat2Q3: "Cosa sono “beni” e “preferenze”?",
    faqCat2A3: "I beni sono gli elementi da dividere o negoziare. Le preferenze sono le valutazioni in stelle per ogni elemento di ciascuna parte, che catturano priorità e intervalli accettabili.",
    faqCat2Q4: "Come viene generata la proposta?",
    faqCat2A4: "Una volta che le parti sono pronte, un motore di teoria dei giochi combina le preferenze di tutti in una proposta equilibrata e basata su prove che puoi esaminare affiancata.",
    faqCat2Q5: "Cosa succede se non accettiamo la proposta?",
    faqCat2A5: "Qualsiasi parte può rifiutare. Il caso può quindi passare a una mediazione strutturata, dove un mediatore coordina e puoi incontrarti tramite video integrato.",
    faqCat2Q6: "Posso esportare il risultato?",
    faqCat2A6: "Sì. Ogni controversia può produrre un rapporto PDF della proposta e una traccia audit CSV delle azioni intraprese, per i tuoi archivi.",
    faqCat3Title: "L'assistente",
    faqCat3Q1: "Cosa può fare l'assistente in controversia?",
    faqCat3A1: "Spiega i termini (“Che cos'è la mediazione?”), suggerisce i prossimi passi e chiarisce i risultati (“Spiega la proposta in termini semplici”). Funziona localmente tramite Ollama.",
    faqCat3Q2: "L'assistente è lo stesso della pagina Legal AI?",
    faqCat3A2: "No. L'assistente per le controversie ti aiuta a utilizzare la piattaforma. Per domande legali, usa la pagina dedicata all'Assistente Legale AI.",
    faqCat3Q3: "I miei messaggi chat sono memorizzati?",
    faqCat3A3: "I messaggi dell'assistente sono conservati nel tuo browser per la controversia attuale, così puoi tornare a consultarli. Non sono condivisi con altre parti.",
    faqCat4Title: "Account, lingua e privacy",
    faqCat4Q1: "Come posso cambiare la mia password o email?",
    faqCat4A1: "Apri “Account” dal menu. Puoi aggiornare la tua email e cambiare la password lì.",
    faqCat4Q2: "Posso cambiare la lingua dell'interfaccia?",
    faqCat4A2: "Sì — usa il selettore di lingua. L'interfaccia è disponibile nelle sette lingue di lavoro del consorzio e cambiare non termina la tua sessione.",
    faqCat4Q3: "Come posso eliminare i miei dati o l'account?",
    faqCat4A3: "In “Account” puoi eliminare i dati della controversia che hai creato, o eliminare permanentemente il tuo intero account e i dati correlati.",
    faqCat4Q4: "La piattaforma è accessibile?",
    faqCat4A4: "Sì. Mira a WCAG AA, è completamente navigabile da tastiera e offre opzioni ad alto contrasto e riduzione del movimento nelle impostazioni.",
    helpTitle: "Aiuto & FAQ",
    helpSubtitle: "Risposte rapide e indicazioni per creare una controversia, impostare preferenze e raggiungere una risoluzione.",
    helpQ1: "Che cos'è una controversia?",
    helpA1: "Una controversia su CREA3 è una procedura strutturata per risolvere un conflitto su come dividere beni. La piattaforma guida ogni parte con strumenti AI e algoritmi di teoria dei giochi verso una risoluzione equa, efficiente e su misura.",
    helpQ2: "Come esprimono le parti le loro preferenze?",
    helpA2: "Ogni parte valuta ogni bene su una scala da 1 a 5 stelle per mostrare quanto sia importante per loro. Queste valutazioni, insieme alla quota di diritto di ogni parte, alimentano la valutazione che produce la proposta.",
    helpQ3: "Come invito i partecipanti a una controversia?",
    helpA3: "1. Apri la tua controversia e vai al passo Partecipanti.\\n\\n2. Aggiungi un partecipante tramite email, con la sua quota di diritto e un ruolo opzionale (parte o mediatore).\\n\\n3. Riceveranno un invito via email e una notifica nell'app, e possono accettare dall'area notifiche.",
    helpQ4: "Come aggiungo beni a una controversia?",
    helpA4: "1. Durante la configurazione, apri il passo Beni.\\n\\n2. Aggiungi ogni bene con un nome e un valore stimato; facoltativamente contrassegnalo come indivisibile.\\n\\n3. Invia per includerlo nel caso.",
    helpQ5: "Come produce CREA3 una soluzione?",
    helpA5: "CREA3 combina le valutazioni delle parti e le quote di diritto e applica algoritmi AI e di teoria dei giochi per generare un'allocazione che mira a soddisfare equamente tutti.\\n\\nLe parti possono accettare o rifiutare la proposta. Se viene rifiutata, è disponibile una mediazione strutturata — con programmazione di videoconferenze.",
    helpQ6: "Cosa succede una volta che tutti accettano la proposta?",
    helpA6: "Quando tutte le parti accettano, CREA3 finalizza il caso e genera un rapporto scaricabile come prova certificata della risoluzione, progettato per futuri flussi di lavoro di certificazione smart-contract / blockchain.",
    helpQ7: "Qual è il progetto europeo CREA3?",
    helpA7: "CREA3 si basa su CREA (2017–19) e CREA2, introducendo strumenti guidati da AI che aiutano gli utenti a risolvere controversie attraverso algoritmi innovativi di teoria dei giochi, un'interfaccia conversazionale intelligente, design di certificazione smart-contract e videoconferenze per mediazione.\\n\\nPuoi leggere l'intero ambito del progetto nella pagina Ambito.",
