    scopeChip3: "Odprtokodno",
    scopeIntro1: "CREA3 prinaša orodja, podprta z AI, in igro-teoretične algoritme za civilno reševanje sporov. Usmerja ljudi korak za korakom k poštenemu, učinkovitemu in prilagojenemu rezultatu ter jim pomaga najti potrebne informacije.",
    scopeIntro2: "Hkrati se ukvarja z razlikami med nacionalnimi pravnimi sistemi držav članic EU, da se čezmejni spori lahko obravnavajo na skupni podlagi.",
    scopeEcgarTitle: "Evropska skupna podlaga razpoložljivih pravic (ECGAR)",
