    othersExt3Body: "Praktični nasveti o pravicah državljanov in podjetij v EU.",
    othersWebsiteTitle: "Spletna stran projekta",
    othersWebsiteBody: "Uradna stran projekta CREA3.",
    faqTitle: "Pogosta vprašanja",
    faqIntro: "Odgovori na pogosta vprašanja o računih, teku spora in platformi.",
    faqSearchPlaceholder: "Išči po pogostih vprašanjih…",
    faqEmpty: "Nobenih vprašanj se ne ujema z vašo iskalno poizvedbo.",
    faqCat1Title: "Začetek",
    faqCat1Q1: "Kako ustvarim račun?",
    faqCat1A1: "Odprite “Registracija”, vnesite svoj e-poštni naslov in geslo ter pošljite. Registracijo in identiteto obravnava naša varna prijavna storitev (Keycloak).",
    faqCat1Q2: "Kako potrdim svoj e-poštni naslov?",
    faqCat1A2: "Po registraciji prejmete potrditveno e-pošto. Odprite povezavo, ki jo vsebuje, da aktivirate svoj račun. Potrditev je obvezna pred prijavo.",
    faqCat1Q3: "Nisem prejel potrditvene e-pošte — kaj zdaj?",
    faqCat1A3: "Najprej preverite mapo za neželeno pošto. Če še vedno ni prispela po nekaj minutah, poskusite prijavo: platforma bo ponudila ponovno pošiljanje potrditvene sporočila.",
    faqCat1Q4: "Zakaj vidim “401 Neavtorizirano”?",
    faqCat1A4: "Vaša seja je potekla ali niste prijavljeni. Ponovno se prijavite; če težava ostaja, se popolnoma odjavite in ponovno prijavite, da osvežite sejo.",
    faqCat2Title: "Tek spora",
    faqCat2Q1: "Kako začnem spor?",
    faqCat2A1: "Iz “Moji spori” ustvarite nov spor, mu dajte naslov, nato določite predmete v obsegu in zabeležite svoje osnovne ocene.",
    faqCat2Q2: "Kdo lahko povabi druge stranke?",
    faqCat2A2: "Samo ustvarjalec spora lahko povabi stranke. Katerekoli stranka lahko povabi mediatorja. Vabila se pošljejo po e-pošti in jih je mogoče sprejeti iz območja obvestil.",
    faqCat2Q3: "Kaj so “blago” in “prednostne možnosti”?",
    faqCat2A3: "Blago so predmeti, ki se delijo ali o katerih se pogaja. Prednostne možnosti so zvezdice za vsak predmet, ki jih dodelijo stranke in zajemajo prioritete ter sprejemljive razpone.",
    faqCat2Q4: "Kako se generira predlog?",
    faqCat2A4: "Ko so stranke pripravljene, igra-teoretični motor združi preference vseh v uravnotežen, na dokazih temelječ predlog, ki ga lahko pregledate ob strani.",
    faqCat2Q5: "Kaj se zgodi, če ne sprejmemo predloga?",
    faqCat2A5: "Katerekoli stranka lahko zavrne. Primer se lahko nato premakne v strukturirano mediacijo, kjer mediator usklajuje in se lahko srečate prek vgrajenega videa.",
    faqCat2Q6: "Ali lahko izvozim izid?",
    faqCat2A6: "Da. Vsak spor lahko ustvari PDF poročilo o predlogu in CSV revizijski sled dejanj, za vaše evidence.",
    faqCat3Title: "Asistent",
    faqCat3Q1: "Kaj lahko stori asistent v sporu?",
    faqCat3A1: "Pojasnjuje pogoje („Kaj je mediacija?“), predlaga naslednje korake in pojasnjuje izhode („Pojasnite predlog v preprostih izrazih“). Deluje lokalno preko Ollama.",
    faqCat3Q2: "Ali je asistent enak strani Pravni AI?",
    faqCat3A2: "Ne. Asistent za spore vam pomaga pri upravljanju platforme. Za pravna vprašanja uporabite stran Pravni AI Asistent.",
    faqCat3Q3: "Ali so moji sporočili shranjeni?",
    faqCat3A3: "Sporočila asistenta se hranijo v vašem brskalniku za trenutni spor, da se lahko nanje vrnete. Niso deljena z drugimi strankami.",
    faqCat4Title: "Račun, jezik in zasebnost",
    faqCat4Q1: "Kako spremenim geslo ali e-pošto?",
    faqCat4A1: "Odprite „Račun“ iz menija. Tam lahko posodobite svojo e-pošto in spremenite geslo.",
    faqCat4Q2: "Ali lahko spremenim jezik vmesnika?",
    faqCat4A2: "Da — uporabite izbirnik jezika. Vmesnik je na voljo v sedmih delovnih jezikih konzorcija, preklapljanje pa ne konča vaše seje.",
    faqCat4Q3: "Kako lahko izbrišem svoje podatke ali račun?",
    faqCat4A3: "V „Računu“ lahko izbrišete podatke o sporu, ki ste jih ustvarili, ali trajno izbrišete celoten račun in njegove povezane podatke.",
    faqCat4Q4: "Ali je platforma dostopna?",
    faqCat4A4: "Da. Cilja na WCAG AA, je popolnoma navigabilna s tipkovnico in ponuja možnosti z visokim kontrastom ter zmanjšanim gibanjem v nastavitvah.",
    helpTitle: "Pomoč & FAQ",
    helpSubtitle: "Hitri odgovori in smernice za ustvarjanje spora, nastavitev preferenc in dosego rešitve.",
    helpQ1: "Kaj je spor?",
    helpA1: "Spor na CREA3 je strukturiran postopek za reševanje konflikta glede delitve dobrin. Platforma vodi vsako stranko z AI orodji in algoritmi teorije iger k pravični, učinkoviti, prilagojeni rešitvi.",
    helpQ2: "Kako stranke izrazijo svoje preference?",
    helpA2: "Vsaka stranka oceni vsako dobrino na lestvici od 1 do 5 zvezdic, da pokaže, kako pomembna je zanje. Te ocene, skupaj z deležem pravice vsake stranke, hranijo oceno, ki proizvaja predlog.",
    helpQ3: "Kako povabim udeležence v spor?",
    helpA3: "1. Odprite svoj spor in pojdite na korak Udeleženci.\\n\\n2. Dodajte udeleženca po e-pošti, z njihovim deležem pravice in neobvezno vlogo (stranka ali mediator).\\n\\n3. Prejmejo e-poštno povabilo in obvestilo v aplikaciji ter lahko sprejmejo iz območja obvestil.",
    helpQ4: "Kako dodam dobrine v spor?",
    helpA4: "1. Med nastavitvijo odprite korak Dobrine.\\n\\n2. Dodajte vsako dobrino z imenom in ocenjeno vrednostjo; neobvezno jo označite kot nedeljivo.\\n\\n3. Pošljite, da jo vključite v primer.",
    helpQ5: "Kako CREA3 proizvaja rešitev?",
    helpA5: "CREA3 združuje ocene strank in deleže pravic ter uporablja AI in algoritme teorije iger za ustvarjanje razdelitve, ki si prizadeva zadovoljiti vse pravično.\\n\\nStranke lahko sprejmejo ali zavrnejo predlog. Če je zavrnjen, je na voljo strukturirana mediacija — z načrtovanjem videokonference.",
    helpQ6: "Kaj se zgodi, ko vsi sprejmejo predlog?",
    helpA6: "Ko vse stranke sprejmejo, CREA3 zaključi primer in ustvari prenosno poročilo kot potrjen dokaz rešitve, zasnovano za prihodnje delovne tokove certificiranja pametnih pogodb / blockchain.",
    helpQ7: "Kaj je evropski projekt CREA3?",
    helpA7: "CREA3 se gradi na CREA (2017–19) in CREA2, uvaja orodja, ki jih poganja AI, ki pomagajo uporabnikom reševati spore preko inovativnih algoritmov teorije iger, pametnega pogovornega vmesnika, zasnove certificiranja pametnih pogodb in videokonferenc za mediacijo.\\n\\nCeloten obseg projekta lahko preberete na strani Obseg.",
