    faqCat1A1: "Avage „Registreeru”, sisestage oma e-post ja parool ning esitage. Registreerimine ja identiteet hallatakse meie turvalise sisselogimisteenuse (Keycloak) kaudu.",
    faqCat1Q2: "Kuidas kinnitada oma e-posti?",
    faqCat1A2: "Pärast registreerimist saate kinnituse e-kirja. Avage link, mis seal on, et aktiveerida oma konto. Kinnitus on kohustuslik enne sisselogimist.",
    faqCat1Q3: "Ma ei saanud kinnituse e-kirja — mis nüüd?",
    faqCat1A3: "Kontrollige esmalt oma rämpsposti kausta. Kui see ei ole pärast mõnda minutit ikka veel saabunud, proovige sisse logida: platvorm pakub võimalust kinnitusteate uuesti saata.",
    faqCat1Q4: "Miks ma näen „401 Autoriseerimata”?",
    faqCat1A4: "Teie seanss on aegunud või te ei ole sisse logitud. Logige uuesti sisse; kui probleem püsib, logige täielikult välja ja logige uuesti sisse, et oma seanssi värskendada.",
    faqCat2Title: "Vaidluse läbiviimine",
    faqCat2Q1: "Kuidas alustada vaidlust?",
    faqCat2A1: "„Minu vaidlustest” looge uus vaidlus, andke sellele pealkiri, seejärel määrake ulatus ja registreerige oma algväärtused.",
    faqCat2Q2: "Kes saab teisi osalisi kutsuda?",
    faqCat2A2: "Ainult vaidluse looja saab kutsuda osalisi. Iga osaline võib kutsuda vahendajat. Kutseid saadetakse e-posti teel ja neid saab aktsepteerida teavituste alalt.",
    faqCat2Q3: "Mis on „kaubad” ja „eelistused”?",
    faqCat2A3: "Kaubad on jagatavad või läbiräägitavad esemed. Eelistused on iga osalise tähtsuse hindamised, mis kajastavad prioriteete ja vastuvõetavaid vahemikke.",
    faqCat2Q4: "Kuidas ettepanek genereeritakse?",
    faqCat2A4: "Kui osalised on valmis, kombineerib mänguteooria mootor kõigi eelistused tasakaalustatud, tõenduspõhiseks ettepanekuks, mida saate kõrvuti üle vaadata.",
    faqCat2Q5: "Mis juhtub, kui me ettepanekut ei aktsepteeri?",
    faqCat2A5: "Iga osaline võib keelduda. Juhtum võib seejärel liikuda struktureeritud vahendusse, kus vahendaja koordineerib ja saate kohtuda sisseehitatud video kaudu.",
    faqCat2Q6: "Kas ma saan tulemuse eksportida?",
    faqCat2A6: "Jah. Iga vaidlus võib genereerida ettepaneku PDF-aruande ja tegevuste CSV-audititee teie jaoks.",
    faqCat3Title: "Abiline",
    faqCat3Q1: "Mida saab vaidluse abiline teha?",
    faqCat3A1: "See selgitab termineid („Mis on vahendus?“), soovitab järgmisi samme ja selgitab tulemusi („Selgita ettepanek lihtsates sõnades“). See töötab kohapeal Ollama kaudu.",
    faqCat3Q2: "Kas assistent on sama mis Õiguslik AI leht?",
    faqCat3A2: "Ei. Vaidluses olev assistent aitab teil platvormi kasutada. Õiguslike küsimuste jaoks kasutage spetsiaalset Õiguslik AI assistendi lehte.",
    faqCat3Q3: "Kas mu vestlusmessid on salvestatud?",
    faqCat3A3: "Assistentide sõnumid hoitakse teie brauseris praeguse vaidluse jaoks, et saaksite neile tagasi pöörduda. Need ei jagata teiste osalistega.",
    faqCat4Title: "Konto, keel ja privaatsus",
    faqCat4Q1: "Kuidas ma saan oma parooli või e-posti muuta?",
    faqCat4A1: "Avage menüüst „Konto“. Seal saate oma e-posti uuendada ja parooli muuta.",
    faqCat4Q2: "Kas ma saan liidese keelt muuta?",
    faqCat4A2: "Jah — kasutage keelevalijat. Liides on saadaval konsortsiumi seitsmes töökeeles ja vahetamine ei lõpeta teie seanssi.",
    faqCat4Q3: "Kuidas ma saan oma andmed või konto kustutada?",
    faqCat4A3: "„Konto“ all saate kustutada loodud vaidluse andmed või püsivalt kustutada kogu oma konto ja sellega seotud andmed.",
    faqCat4Q4: "Kas platvorm on ligipääsetav?",
    faqCat4A4: "Jah. See järgib WCAG AA standardit, on täielikult klaviatuuriga navigeeritav ning pakub seadetes kõrge kontrasti ja vähendatud liikumise valikuid.",
    helpTitle: "Abi ja KKK",
    helpSubtitle: "Kiired vastused ja juhised vaidluse loomise, eelistuste seadistamise ja lahenduse saavutamise kohta.",
    helpQ1: "Mis on vaidlus?",
    helpA1: "Vaidlus CREA3-s on struktureeritud protseduur konflikti lahendamiseks kaupade jagamise üle. Platvorm juhendab iga osalist AI tööriistade ja mänguteoreetiliste algoritmide abil õiglaselt, tõhusalt ja kohandatult lahenduse suunas.",
    helpQ2: "Kuidas osalised oma eelistusi väljendavad?",
    helpA2: "Iga osaline hindab iga kaupa 1–5 tärni skaalal, et näidata, kui oluline see neile on. Need hinnangud koos iga osalise õiguse osaga toidavad hindamist, mis genereerib ettepaneku.",
    helpQ3: "Kuidas ma saan osalejaid vaidlusse kutsuda?",
    helpA3: "1. Avage oma vaidlus ja minge osalejate sammu.\\n\\n2. Lisage osaline e-posti teel, koos tema õiguse osaga ja valikulise rolliga (osaline või vahendaja).\\n\\n3. Nad saavad e-posti kutse ja rakenduses teate ning saavad kutse aktsepteerida teateala kaudu.",
    helpQ4: "Kuidas ma saan kaupu vaidlusse lisada?",
    helpA4: "1. Seadistamise ajal avage kaupade samm.\\n\\n2. Lisage iga kaup nime ja hinnangulise väärtusega; valikuliselt märkige see kui jagamatu.\\n\\n3. Esitage, et see kaasata juhtumisse.",
    helpQ5: "Kuidas CREA3 lahenduse genereerib?",
    helpA5: "CREA3 kombineerib osaliste hinnangud ja õiguse osad ning rakendab AI ja mänguteoreetilisi algoritme, et genereerida jaotuse, mis püüab kõiki õiglaselt rahuldada.\\n\\nOsalised saavad ettepaneku aktsepteerida või tagasi lükata. Kui see on tagasi lükatud, on saadaval struktureeritud vahendus — koos videokonverentsi ajakava seadistamisega.",
    helpQ6: "Mis juhtub, kui kõik aktsepteerivad ettepaneku?",
    helpA6: "Kui kõik osalised aktsepteerivad, lõpetab CREA3 juhtumi ja genereerib allalaaditava aruande kui sertifitseeritud tõendi lahenduse kohta, mis on mõeldud tulevaste nutilepingute / plokiahela sertifitseerimise töövoogude jaoks.",
    helpQ7: "Mis on CREA3 Euroopa projekt?",
    helpA7: "CREA3 põhineb CREA-l (2017–19) ja CREA2-l, tutvustades AI-põhiseid tööriistu, mis aitavad kasutajatel vaidlusi lahendada uuenduslike mänguteoreetiliste algoritmide, nutika vestlusliidese, nutilepingute sertifitseerimise disaini ja videokonverentside kaudu vahendamiseks.\\n\\nTäieliku projekti ulatuse kohta saate lugeda ulatuse lehelt.",
    dispInviteTitle: "Teid on kutsutud sellele vaidlusele",
