    scopeTagline: "AI pagalba, žaidimų teorijos pagrindu veikiantis internetinis ginčų sprendimas Europai.",
    scopeChip1: "Remiasi CREA ir CREA2",
    scopeChip2: "ES JUST programa",
    scopeChip3: "Atvirojo kodo",
    scopeIntro1: "CREA3 suteikia AI valdomus įrankius ir žaidimų teorijos algoritmus civiliniam ginčų sprendimui. Jis žingsnis po žingsnio veda žmones link teisingo, efektyvaus ir pritaikyto rezultato, padėdamas jiems rasti reikiamą informaciją.",
    scopeIntro2: "Lygiagrečiai jis sprendžia skirtumus tarp ES valstybių narių nacionalinių teisinių sistemų, kad tarptautiniai ginčai būtų sprendžiami bendroje erdvėje.",
    scopeEcgarTitle: "Europos bendroji teisė (ECGAR)",
    scopeEcgarText: "Kiekvienos valstybės narės privalomi teisės aktai yra atmetami, o procedūra vyksta remiantis likusiomis „prieinamomis teisėmis“. Tikslas – išplėsti prieigą prie internetinio ginčų sprendimo (ODR) ir sumažinti struktūrinius teisingumo barjerus.",
    scopeWpHeading: "Tris inovacijos",
    scopeWp1Title: "Teisės ir AI standartai",
    scopeWp1Body: "Susieja ECGAR su žaidimų teorijos modeliu, kad nustatytų tikslius teisės ir AI integravimo standartus.",
    scopeWp2Title: "Išmanusis pokalbių sąsaja",
    scopeWp2Body: "Mašininio mokymosi įrankiai suteikia asistentą, kuris veda praktiką, teisininkus ir paprastus vartotojus per visą procedūrą.",
    scopeWp3Title: "Blockchain sertifikavimas",
    scopeWp3Body: "Išmaniojo kontrakto technologija, sukurta naudojant DApp dizaino metodologiją, sertifikuoja pasiektą susitarimą tarp šalių.",
    scopeVideoNote: "Įmontuota vaizdo konferencijų funkcija leidžia mediatoriams susitikti su abiem šalimis platformoje (WP3).",
    scopeAudienceHeading: "Kam tai skirta",
    scopeAudienceNote: "CREA3 tobulina esamą CREA platformą ir yra išleidžiamas kaip atvirojo kodo, skirtas plačiam ES suinteresuotųjų šalių ratui.",
    scopeStat1: "Teisininkai",
