    othersWebsiteTitle: "Projekto svetainė",
    othersWebsiteBody: "Oficiali CREA3 projekto puslapis.",
    faqTitle: "DUK",
    faqIntro: "Atsakymai į dažniausiai užduodamus klausimus apie paskyras, ginčų vedimą ir platformą.",
    faqSearchPlaceholder: "Ieškoti DUK…",
    faqEmpty: "Nėra klausimų, atitinkančių jūsų paiešką.",
    faqCat1Title: "Pradžia",
    faqCat1Q1: "Kaip sukurti paskyrą?",
    faqCat1A1: "Atidarykite „Registruotis“, įveskite savo el. paštą ir slaptažodį, tada pateikite. Registracija ir tapatybė tvarkoma mūsų saugiame prisijungimo paslaugoje (Keycloak).",
    faqCat1Q2: "Kaip patvirtinti savo el. paštą?",
    faqCat1A2: "Po registracijos gausite patvirtinimo el. laišką. Atidarykite jame esantį nuorodą, kad aktyvuotumėte savo paskyrą. Patvirtinimas yra privalomas prieš prisijungiant.",
    faqCat1Q3: "Negavau patvirtinimo el. laiško — ką daryti?",
    faqCat1A3: "Pirmiausia patikrinkite savo šlamšto aplanką. Jei jis vis dar neatsirado po kelių minučių, bandykite prisijungti: platforma pasiūlys persiųsti patvirtinimo žinutę.",
    faqCat1Q4: "Kodėl matau „401 Neautorizuota“?",
    faqCat1A4: "Jūsų sesija pasibaigė arba nesate prisijungę. Prisijunkite dar kartą; jei problema išlieka, visiškai atsijunkite ir vėl prisijunkite, kad atnaujintumėte sesiją.",
    faqCat2Title: "Ginčo vedimas",
    faqCat2Q1: "Kaip pradėti ginčą?",
    faqCat2A1: "Iš „Mano ginčai“ sukurkite naują ginčą, suteikite jam pavadinimą, tada apibrėžkite apimtį ir užfiksuokite savo pradinius vertinimus.",
    faqCat2Q2: "Kas gali pakviesti kitas šalis?",
    faqCat2A2: "Tik ginčo kūrėjas gali pakviesti šalis. Bet kuri šalis gali pakviesti mediatorius. Kviečiami el. paštu, ir kvietimus galima priimti iš pranešimų srities.",
    faqCat2Q3: "Kas yra „prekės“ ir „pageidavimai“?",
    faqCat2A3: "Prekės yra dalijamasi arba derinamos prekės. Pageidavimai yra kiekvienos šalies žvaigždučių įvertinimai, kurie fiksuoja prioritetus ir priimtinas ribas.",
    faqCat2Q4: "Kaip generuojamas pasiūlymas?",
    faqCat2A4: "Kai šalys yra pasiruošusios, žaidimų teorijos variklis sujungia visų pageidavimus į subalansuotą, įrodymais pagrįstą pasiūlymą, kurį galite peržiūrėti šalia.",
    faqCat2Q5: "Ką daryti, jei nesutinkame su pasiūlymu?",
    faqCat2A5: "Bet kuri šalis gali atsisakyti. Tada byla gali pereiti į struktūruotą mediaciją, kur mediatorius koordinuoja ir galite susitikti per integruotą vaizdo skambutį.",
    faqCat2Q6: "Ar galiu eksportuoti rezultatą?",
    faqCat2A6: "Taip. Kiekvienas ginčas gali sukurti PDF ataskaitą apie pasiūlymą ir CSV auditą apie atliktus veiksmus, jūsų įrašams.",
    faqCat3Title: "Asistentas",
    faqCat3Q1: "Ką gali daryti ginčo asistentas?",
    faqCat3A1: "Tai paaiškina terminus („Kas yra mediacija?“), siūlo kitus žingsnius ir aiškina rezultatus („Paaiškinkite pasiūlymą paprastais žodžiais“). Veikia lokaliai per Ollama.",
    faqCat3Q2: "Ar asistentas yra tas pats, kas Teisinės AI puslapis?",
    faqCat3A2: "Ne. Ginčo asistentas padeda jums naudotis platforma. Teisiniams klausimams naudokite specialų Teisinės AI asistento puslapį.",
    faqCat3Q3: "Ar mano pokalbių žinutės saugomos?",
    faqCat3A3: "Asistento žinutės saugomos jūsų naršyklėje dabartiniam ginčui, kad galėtumėte prie jų grįžti. Jos nesidalinamos su kitomis šalimis.",
    faqCat4Title: "Paskyra, kalba ir privatumas",
    faqCat4Q1: "Kaip pakeisti slaptažodį ar el. paštą?",
    faqCat4A1: "Atidarykite „Paskyra“ iš meniu. Ten galite atnaujinti savo el. paštą ir pakeisti slaptažodį.",
    faqCat4Q2: "Ar galiu pakeisti sąsajos kalbą?",
    faqCat4A2: "Taip — naudokite kalbos pasirinkiklį. Sąsaja prieinama septyniomis konsorciumo darbo kalbomis, o perjungimas nesibaigia jūsų sesija.",
    faqCat4Q3: "Kaip ištrinti savo duomenis ar paskyrą?",
    faqCat4A3: "„Paskyroje“ galite ištrinti sukurtus ginčo duomenis arba visam laikui ištrinti visą paskyrą ir jos susijusius duomenis.",
    faqCat4Q4: "Ar platforma yra prieinama?",
    faqCat4A4: "Taip. Ji atitinka WCAG AA, visiškai valdomas klaviatūra ir siūlo didelio kontrasto bei sumažinto judesio parinktis nustatymuose.",
    helpTitle: "Pagalba & DUK",
    helpSubtitle: "Greiti atsakymai ir gairės, kaip sukurti ginčą, nustatyti pageidavimus ir pasiekti sprendimą.",
    helpQ1: "Kas yra ginčas?",
    helpA1: "Ginčas CREA3 yra struktūrizuota procedūra, skirta spręsti konfliktus dėl prekių pasidalijimo. Platforma kiekvienai šaliai teikia AI įrankius ir žaidimų teorijos algoritmus, siekdama teisingo, efektyvaus, pritaikyto sprendimo.",
    helpQ2: "Kaip šalys išreiškia savo pageidavimus?",
    helpA2: "Kiekviena šalis vertina kiekvieną prekę 1–5 žvaigždučių skalėje, kad parodytų, kiek tai jiems svarbu. Šie vertinimai, kartu su kiekvienos šalies teisių dalimi, sudaro vertinimą, kuris sukuria pasiūlymą.",
    helpQ3: "Kaip pakviesti dalyvius į ginčą?",
    helpA3: "1. Atidarykite savo ginčą ir eikite į Dalyvių žingsnį.\\n\\n2. Pridėkite dalyvį el. paštu, nurodydami jų teisių dalį ir pasirenkamą vaidmenį (šalis arba mediatorius).\\n\\n3. Jie gaus el. pašto kvietimą ir pranešimą programėlėje, ir galės priimti iš pranešimų srities.",
    helpQ4: "Kaip pridėti prekes prie ginčo?",
    helpA4: "1. Nustatymo metu atidarykite Prekių žingsnį.\\n\\n2. Pridėkite kiekvieną prekę su pavadinimu ir numatoma verte; pasirenkamai pažymėkite kaip nedaloma.\\n\\n3. Pateikite, kad įtrauktumėte ją į bylą.",
    helpQ5: "Kaip CREA3 sukuria sprendimą?",
    helpA5: "CREA3 sujungia šalių vertinimus ir teisių dalis, taiko AI ir žaidimų teorijos algoritmus, kad sukurtų paskirstymą, kuris siekia teisingai patenkinti visus.\\n\\nŠalys gali priimti arba atmesti pasiūlymą. Jei jis atmestas, siūloma struktūrizuota mediacija — su vaizdo konferencijų planavimu.",
    helpQ6: "Kas nutinka, kai visi priima pasiūlymą?",
    helpA6: "Kai visos šalys priima, CREA3 užbaigia bylą ir sugeneruoja atsisiunčiamą ataskaitą kaip sertifikuotą įrodymą apie sprendimą, skirtą būsimoms išmaniosioms sutarčių / blokų grandinės sertifikavimo darbo eigoms.",
    helpQ7: "Kas yra CREA3 Europos projektas?",
    helpA7: "CREA3 remiasi CREA (2017–19) ir CREA2, pristatydama AI valdomus įrankius, kurie padeda vartotojams spręsti ginčus per novatoriškus žaidimų teorijos algoritmus, išmanią pokalbių sąsają, išmaniojo sutarčių sertifikavimo dizainą ir vaizdo konferencijas mediacijai.\\n\\nVisą projekto apimtį galite perskaityti Apimties puslapyje.",
    dispInviteTitle: "Jūs buvote pakviestas į šią ginčą",
    dispInviteBody: "Priimkite, kad gautumėte prieigą prie juodraščių ir pateiktumėte pageidavimus. Atmesti, kad pašalintumėte prieigą.",
