    scopeIntro1: "CREA3 donosi alate vođene AI-jem i teorijske algoritme igara u civilno rješavanje sporova. Vodi ljude korak po korak prema pravednom, učinkovitom i prilagođenom ishodu, pomažući im da pronađu potrebne informacije.",
    scopeIntro2: "Paralelno, rješava razlike između nacionalnih pravnih sustava država članica EU-a kako bi se prekogranični sporovi mogli rješavati na zajedničkoj osnovi.",
