    othersWebsiteTitle: "Web stranica projekta",
    othersWebsiteBody: "Službena stranica projekta CREA3.",
    faqTitle: "Česta pitanja",
    faqIntro: "Odgovori na uobičajena pitanja o računima, vođenju spora i platformi.",
    faqSearchPlaceholder: "Pretraži česta pitanja…",
    faqEmpty: "Nema pitanja koja odgovaraju vašem pretraživanju.",
    faqCat1Title: "Kako započeti",
    faqCat1Q1: "Kako mogu kreirati račun?",
    faqCat1A1: "Otvorite “Registracija”, unesite svoj email i lozinku, te pošaljite. Registracija i identitet se obrađuju putem naše sigurne usluge prijave (Keycloak).",
    faqCat1Q2: "Kako mogu verificirati svoj email?",
    faqCat1A2: "Nakon registracije primite email za verifikaciju. Otvorite poveznicu koju sadrži kako biste aktivirali svoj račun. Verifikacija je obavezna prije nego se možete prijaviti.",
    faqCat1Q3: "Nisam primio email za verifikaciju — što sada?",
    faqCat1A3: "Prvo provjerite svoju mapu neželjene pošte. Ako još uvijek nije stigao nakon nekoliko minuta, pokušajte se prijaviti: platforma će ponuditi ponovno slanje poruke za verifikaciju.",
    faqCat1Q4: "Zašto vidim “401 Unauthorized”?",
    faqCat1A4: "Vaša sesija je istekla ili niste prijavljeni. Ponovno se prijavite; ako se problem nastavi, potpuno se odjavite i ponovno prijavite kako biste osvježili svoju sesiju.",
    faqCat2Title: "Vođenje spora",
    faqCat2Q1: "Kako mogu započeti spor?",
    faqCat2A1: "Iz “Moji sporovi”, kreirajte novi spor, dajte mu naslov, zatim definirajte stavke u opsegu i zabilježite svoje osnovne procjene.",
    faqCat2Q2: "Tko može pozvati druge strane?",
    faqCat2A2: "Samo kreator spora može pozvati strane. Svaka strana može pozvati posrednika. Pozivnice se šalju putem emaila i mogu se prihvatiti iz područja obavijesti.",
    faqCat2Q3: "Što su “dobara” i “preferencije”?",
    faqCat2A3: "Dobra su stavke koje se dijele ili pregovaraju. Preferencije su zvjezdaste ocjene po stavkama svake strane, koje odražavaju prioritete i prihvatljive rasponi.",
    faqCat2Q4: "Kako se generira prijedlog?",
    faqCat2A4: "Kada su strane spremne, motor teorije igara kombinira preferencije svih u uravnotežen, na dokazima temeljen prijedlog koji možete pregledati usporedno.",
    faqCat2Q5: "Što se događa ako ne prihvatimo prijedlog?",
    faqCat2A5: "Svaka strana može odbiti. Tada se slučaj može prebaciti na strukturiranu medijaciju, gdje posrednik koordinira i možete se sastati putem ugrađenog videa.",
    faqCat2Q6: "Mogu li izvesti ishod?",
    faqCat2A6: "Da. Svaki spor može proizvesti PDF izvještaj o prijedlogu i CSV evidenciju poduzetih radnji, za vaše evidencije.",
    faqCat3Title: "Asistent",
    faqCat3Q1: "Što može učiniti asistent u sporu?",
    faqCat3A1: "Objašnjava pojmove („Što je medijacija?“), predlaže sljedeće korake i pojašnjava rezultate („Objasnite prijedlog jednostavnim riječima“). Radi lokalno putem Ollama.",
    faqCat3Q2: "Je li asistent isti kao stranica Legal AI?",
    faqCat3A2: "Ne. Asistent za spor pomaže vam u radu s platformom. Za pravna pitanja, koristite stranicu posvećenu Legal AI Asistentu.",
    faqCat3Q3: "Spremaju li se moje poruke u chatu?",
    faqCat3A3: "Poruke asistenta čuvaju se u vašem pregledniku za trenutni spor, tako da im možete pristupiti. Nisu dijeljene s drugim stranama.",
    faqCat4Title: "Račun, jezik i privatnost",
    faqCat4Q1: "Kako mogu promijeniti svoju lozinku ili email?",
    faqCat4A1: "Otvorite „Račun” iz izbornika. Tamo možete ažurirati svoj email i promijeniti lozinku.",
    faqCat4Q2: "Mogu li promijeniti jezik sučelja?",
    faqCat4A2: "Da — koristite odabir jezika. Sučelje je dostupno na sedam radnih jezika konzorcija, a promjena ne prekida vašu sesiju.",
    faqCat4Q3: "Kako mogu izbrisati svoje podatke ili račun?",
    faqCat4A3: "U „Računu” možete izbrisati podatke o sporu koje ste stvorili ili trajno izbrisati cijeli svoj račun i povezane podatke.",
    faqCat4Q4: "Je li platforma dostupna?",
    faqCat4A4: "Da. Cilja na WCAG AA, potpuno je navigabilna putem tipkovnice i nudi opcije visokog kontrasta i smanjene pokretljivosti u postavkama.",
    helpTitle: "Pomoć & FAQ",
    helpSubtitle: "Brzi odgovori i smjernice za stvaranje spora, postavljanje preferencija i postizanje rješenja.",
    helpQ1: "Što je spor?",
    helpA1: "Spor na CREA3 je strukturirani postupak za rješavanje sukoba oko podjele dobara. Platforma vodi svaku stranu s AI alatima i algoritmima teorije igara prema pravednom, učinkovitom, prilagođenom rješenju.",
    helpQ2: "Kako strane izražavaju svoje preferencije?",
    helpA2: "Svaka strana ocjenjuje svako dobro na ljestvici od 1 do 5 zvjezdica kako bi pokazala koliko im je važno. Ove ocjene, zajedno s dijelom prava svake strane, hrane evaluaciju koja proizvodi prijedlog.",
    helpQ3: "Kako mogu pozvati sudionike u spor?",
    helpA3: "1. Otvorite svoj spor i idite na korak Sudionici.\\n\\n2. Dodajte sudionika putem emaila, s njihovim dijelom prava i opcionalnom ulogom (strana ili posrednik).\\n\\n3. Oni primaju email pozivnicu i obavijest unutar aplikacije, te mogu prihvatiti iz područja obavijesti.",
    helpQ4: "Kako mogu dodati dobra u spor?",
    helpA4: "1. Tijekom postavljanja, otvorite korak Dobra.\\n\\n2. Dodajte svako dobro s imenom i procijenjenom vrijednošću; opcionalno označite kao nedjeljivo.\\n\\n3. Pošaljite da biste ga uključili u slučaj.",
    helpQ5: "Kako CREA3 proizvodi rješenje?",
    helpA5: "CREA3 kombinira ocjene strana i dijelove prava te primjenjuje AI i algoritme teorije igara kako bi generirao raspodjelu koja ima za cilj pravedno zadovoljstvo svih.\\n\\nStrane mogu prihvatiti ili odbiti prijedlog. Ako je odbijen, dostupna je strukturirana medijacija — s rasporedom video konferencija.",
    helpQ6: "Što se događa kada svi prihvate prijedlog?",
    helpA6: "Kada sve strane prihvate, CREA3 finalizira slučaj i generira preuzimajući izvještaj kao ovjereni dokaz rješenja, dizajniran za buduće radne tokove certifikacije pametnih ugovora / blockchaina.",
    helpQ7: "Što je CREA3 europski projekt?",
    helpA7: "CREA3 se temelji na projektu CREA (2017–19) i CREA2, uvodeći alate vođene AI koji pomažu korisnicima u rješavanju sporova kroz inovativne algoritme teorije igara, pametno konverzacijsko sučelje, dizajn certifikacije pametnih ugovora i video konferencije za medijaciju.\\n\\nMožete pročitati cijeli opseg projekta na stranici Opseg.",
    dispInviteTitle: "Pozvani ste na ovaj spor",
    dispInviteBody: "Prihvatite za pristup nacrtima i podnošenje preferencija. Odbijte za uklanjanje pristupa.",
    dispNotAuthorized: "Niste ovlašteni.",
    dispNoAgents: "Još nema agenata.",
