    scopeTitle: "CREA3 — Conflictresolutie met Equitative Algoritmen",
    scopeTagline: "AI-ondersteunde, speltheoretische online geschiloplossing voor Europa.",
    scopeChip1: "Bouwt voort op CREA & CREA2",
    scopeChip2: "EU JUST Programma",
    scopeChip3: "Open source",
    scopeIntro1: "CREA3 brengt AI-gedreven tools en speltheoretische algoritmen naar de civiele geschiloplossing. Het begeleidt mensen stap voor stap naar een eerlijke, efficiënte en op maat gemaakte uitkomst, en helpt hen de informatie te vinden die ze onderweg nodig hebben.",
    scopeIntro2: "Tegelijkertijd pakt het de verschillen tussen de nationale rechtssystemen van de EU-lidstaten aan, zodat grensoverschrijdende geschillen op gemeenschappelijke basis kunnen worden behandeld.",
    scopeEcgarTitle: "Europees Gemeenschappelijk Grond van Beschikbare Rechten (ECGAR)",
    scopeEcgarText: "De verplichte regels van elke lidstaat worden opzijgezet en de procedure werkt op de resterende 'beschikbare rechten'. Het doel is om de toegang tot Online Geschiloplossing (ODR) te verbreden en structurele barrières voor gerechtigheid te verminderen.",
    scopeWpHeading: "Drie innovaties",
    scopeWp1Title: "Wet- & AI-normen",
    scopeWp1Body: "Verbindt de ECGAR met het speltheoretische model om nauwkeurige normen voor de integratie van recht en AI vast te stellen.",
    scopeWp2Title: "Slimme conversatie-interface",
    scopeWp2Body: "Machine-learningtools ondersteunen een assistent die beoefenaars, juridische professionals en gewone gebruikers door de hele procedure begeleidt.",
    scopeWp3Title: "Blockchain-certificering",
    scopeWp3Body: "Slim-contracttechnologie, gebouwd met een DApp-ontwerpmethodologie, certificeert de overeenkomst die tussen de partijen is bereikt.",
    scopeVideoNote: "Een ingebouwde videoconferentiefunctie laat de mediator beide partijen binnen het platform ontmoeten (WP3).",
    scopeAudienceHeading: "Voor wie het is",
    scopeAudienceNote: "CREA3 verbetert het bestaande CREA-platform en wordt als open source vrijgegeven, voor een breed scala aan EU-belanghebbenden.",
