    othersExt3Body: "Praktische richtlijnen over de rechten van burgers en bedrijven in de EU.",
    othersWebsiteTitle: "Projectwebsite",
    othersWebsiteBody: "De officiële CREA3 projectpagina.",
    faqTitle: "Veelgestelde vragen",
    faqIntro: "Antwoorden op veelgestelde vragen over accounts, het voeren van een geschil en het platform.",
    faqSearchPlaceholder: "Zoek de veelgestelde vragen…",
    faqEmpty: "Geen vragen passen bij je zoekopdracht.",
    faqCat1Title: "Aan de slag",
    faqCat1Q1: "Hoe maak ik een account aan?",
    faqCat1A1: "Open “Registreren”, voer je e-mail en een wachtwoord in en dien dit in. Registratie en identiteit worden afgehandeld door onze veilige inlogdienst (Keycloak).",
    faqCat1Q2: "Hoe verifieer ik mijn e-mail?",
    faqCat1A2: "Na registratie ontvang je een verificatie-e-mail. Open de link die deze bevat om je account te activeren. Verificatie is verplicht voordat je kunt inloggen.",
    faqCat1Q3: "Ik heb de verificatie-e-mail niet ontvangen — wat nu?",
    faqCat1A3: "Controleer eerst je spamfolder. Als deze na een paar minuten nog niet is aangekomen, probeer dan in te loggen: het platform biedt aan de verificatieboodschap opnieuw te verzenden.",
    faqCat1Q4: "Waarom zie ik “401 Unauthorized”?",
    faqCat1A4: "Je sessie is verlopen of je bent niet ingelogd. Log opnieuw in; als het probleem aanhoudt, log dan volledig uit en weer in om je sessie te vernieuwen.",
    faqCat2Title: "Een geschil voeren",
    faqCat2Q1: "Hoe begin ik een geschil?",
    faqCat2A1: "Ga naar “Mijn geschillen”, maak een nieuw geschil aan, geef het een titel en definieer de items in scope en noteer je basiswaarderingen.",
    faqCat2Q2: "Wie kan de andere partijen uitnodigen?",
    faqCat2A2: "Alleen de geschilmaker kan partijen uitnodigen. Elke partij kan een mediator uitnodigen. Uitnodigingen worden per e-mail verzonden en kunnen vanuit het meldingengebied worden geaccepteerd.",
    faqCat2Q3: "Wat zijn “goederen” en “voorkeuren”?",
    faqCat2A3: "Goederen zijn de items die verdeeld of onderhandeld worden. Voorkeuren zijn de sterbeoordelingen per item van elke partij, die prioriteiten en acceptabele reeksen vastleggen.",
    faqCat2Q4: "Hoe wordt het voorstel gegenereerd?",
    faqCat2A4: "Zodra partijen klaar zijn, combineert een speltheoretische engine ieders voorkeuren in een gebalanceerd, op bewijs gebaseerd voorstel dat je zij aan zij kunt bekijken.",
    faqCat2Q5: "Wat gebeurt er als we het voorstel niet accepteren?",
    faqCat2A5: "Elke partij kan weigeren. De zaak kan dan overgaan naar gestructureerde mediation, waar een mediator coördineert en je kunt vergaderen via ingebouwde video.",
    faqCat2Q6: "Kan ik de uitkomst exporteren?",
    faqCat2A6: "Ja. Elk geschil kan een PDF-rapport van het voorstel en een CSV-audittrail van de genomen acties genereren, voor je administratie.",
    faqCat3Title: "De assistent",
    faqCat3Q1: "Wat kan de assistent in geschil doen?",
    faqCat3A1: "Het legt termen uit (“Wat is mediation?”), suggereert volgende stappen en verduidelijkt resultaten (“Leg het voorstel in eenvoudige termen uit”). Het draait lokaal via Ollama.",
    faqCat3Q2: "Is de assistent hetzelfde als de Legal AI-pagina?",
    faqCat3A2: "Nee. De assistent bij geschillen helpt je de platform te gebruiken. Voor juridische vragen gebruik je de speciale Legal AI Assistant-pagina.",
    faqCat3Q3: "Worden mijn chatberichten opgeslagen?",
    faqCat3A3: "Assistentberichten worden in je browser bewaard voor het huidige geschil, zodat je ze kunt terugzien. Ze worden niet gedeeld met andere partijen.",
    faqCat4Title: "Account, taal & privacy",
    faqCat4Q1: "Hoe wijzig ik mijn wachtwoord of e-mail?",
    faqCat4A1: "Open “Account” in het menu. Je kunt daar je e-mail bijwerken en je wachtwoord wijzigen.",
    faqCat4Q2: "Kan ik de interface-taal wijzigen?",
    faqCat4A2: "Ja — gebruik de taalselector. De interface is beschikbaar in de zeven werkende talen van het consortium, en wisselen beëindigt je sessie niet.",
    faqCat4Q3: "Hoe verwijder ik mijn gegevens of account?",
    faqCat4A3: "In “Account” kun je de geschilgegevens die je hebt aangemaakt verwijderen, of je hele account en de bijbehorende gegevens permanent verwijderen.",
    faqCat4Q4: "Is het platform toegankelijk?",
    faqCat4A4: "Ja. Het richt zich op WCAG AA, is volledig met het toetsenbord navigeerbaar en biedt opties voor hoog contrast en verminderde beweging in de instellingen.",
    helpTitle: "Help & FAQ",
    helpSubtitle: "Snelle antwoorden en begeleiding voor het creëren van een geschil, het instellen van voorkeuren en het bereiken van een oplossing.",
    helpQ1: "Wat is een geschil?",
    helpA1: "Een geschil op CREA3 is een gestructureerde procedure voor het oplossen van een conflict over hoe goederen te verdelen. Het platform begeleidt elke partij met AI-tools en speltheoretische algoritmen naar een eerlijke, efficiënte, op maat gemaakte oplossing.",
    helpQ2: "Hoe drukken partijen hun voorkeuren uit?",
    helpA2: "Elke partij beoordeelt elk goed op een schaal van 1–5 sterren om aan te geven hoe belangrijk het voor hen is. Deze beoordelingen, samen met het recht op aandeel van elke partij, voeden de evaluatie die het voorstel produceert.",
    helpQ3: "Hoe nodig ik deelnemers uit voor een geschil?",
    helpA3: "1. Open je geschil en ga naar de stap Deelnemers.\\n\\n2. Voeg een deelnemer toe via e-mail, met hun aandeel in het recht en een optionele rol (partij of mediator).\\n\\n3. Ze ontvangen een e-mailuitnodiging en een in-app notificatie, en kunnen accepteren vanuit het notificatiegebied.",
    helpQ4: "Hoe voeg ik goederen toe aan een geschil?",
    helpA4: "1. Open tijdens de setup de stap Goederen.\\n\\n2. Voeg elk goed toe met een naam en geschatte waarde; markeer het optioneel als ondeelbaar.\\n\\n3. Dien het in om het in de zaak op te nemen.",
    helpQ5: "Hoe produceert CREA3 een oplossing?",
    helpA5: "CREA3 combineert de beoordelingen en recht op aandelen van de partijen en past AI en speltheoretische algoritmen toe om een toewijzing te genereren die iedereen eerlijk probeert te voldoen.\\n\\nPartijen kunnen het voorstel accepteren of afwijzen. Als het wordt afgewezen, is gestructureerde mediation — met video-conferentieplanning — beschikbaar.",
    helpQ6: "Wat gebeurt er zodra iedereen het voorstel accepteert?",
    helpA6: "Wanneer alle partijen accepteren, finaliseert CREA3 de zaak en genereert een downloadbaar rapport als gecertificeerd bewijs van de oplossing, ontworpen voor toekomstige smart-contract / blockchain-certificeringsworkflows.",
    helpQ7: "Wat is het CREA3 Europese project?",
    helpA7: "CREA3 bouwt voort op CREA (2017–19) en CREA2, en introduceert AI-gedreven tools die gebruikers helpen geschillen op te lossen via innovatieve speltheoretische algoritmen, een slimme conversatie-interface, ontwerp voor smart-contract certificering en video-conferenties voor mediation.\\n\\nJe kunt de volledige projectomvang lezen op de Scope-pagina.",
