export type I18nKey = keyof typeof strings['en']

const Ctx = createContext<I18nState | null>(null)

function detectDefault(): Lang {
  try {
    const saved = localStorage.getItem(LS_LANG) as Lang | null
    if (saved === 'en' || saved === 'it' || saved === 'sl' || saved === 'et' || saved === 'be' || saved === 'lt' || saved === 'hr' || saved === 'nl') return saved
  } catch {}
  try {
    const n = navigator.language?.toLowerCase() || ''
    if (n.startsWith('it')) return 'it'
    if (n.startsWith('sl')) return 'sl'
    if (n.startsWith('et')) return 'et'
    if (n.startsWith('lt')) return 'lt'
    if (n.startsWith('hr')) return 'hr'
    if (n.startsWith('nl')) return 'nl'   // Belgium (Dutch)
    if (n.startsWith('fr')) return 'be'   // Belgium (French)
  } catch {}
  return 'en'
}

function toHtmlLang(l: Lang) {
  switch (l) {
    case 'en':
      return 'en'
    case 'it':
      return 'it'
    case 'sl':
      return 'sl'
    case 'et':
      return 'et'
    case 'lt':
      return 'lt'
    case 'hr':
      return 'hr'
    case 'be':
      return 'fr-BE'
    case 'nl':
      return 'nl-BE'
    default:
      return 'en'
  }
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => detectDefault())

  const setLang = (l: Lang) => {
    setLangState(l)
    try { localStorage.setItem(LS_LANG, l) } catch {}
    try { document.documentElement.setAttribute('lang', toHtmlLang(l)) } catch {}
  }

  const t = useMemo(() => {
    // English is the source of truth for the key set; other locales are treated
    // as a partial of it and fall back to English for any key they don't define.
    const current = strings[lang] as Partial<typeof strings['en']>
    return (key: keyof typeof strings['en'], vars?: Record<string, string | number>) => {
      let out = (current[key] || strings.en[key]) as string
      if (vars) {
        for (const k of Object.keys(vars)) {
          out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(vars[k]))
        }
      }
      return out
    }
  }, [lang])

  const value: I18nState = { lang, setLang, t }
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>
}

export function useI18n() {
  const ctx = useContext(Ctx)
  if (!ctx) throw new Error('useI18n must be used inside I18nProvider')
  return ctx
}

export const I18N_STRINGS = strings
